def get_best_match(span, entries, station):
    best_entry = None
    best_score = -1

    cleaned_span = clean_span(span)
    if not cleaned_span:
        return None, 0.0

    for entry in entries:
        scope = str(entry.get('station_scope', '')).split(';')
        station_bonus = 0
        if station in scope:
            station_bonus = 1.0

        score = calculate_match_score(cleaned_span, entry) + station_bonus
        if score > best_score:
            best_score = score
            best_entry = entry

    # Engineering calibration for confidence
    # Base score can go up to ~15.
    if best_entry and best_score >= 2.0:
        # Logistic-like scaling for confidence to have good diversity
        confidence = 1.0 / (1.0 + 2.718 ** (-(best_score - 4.0) / 1.5))
        confidence = round(max(0.2, min(0.99, confidence)), 3)

        return {
            "pred_code": best_entry['code'],
            "pred_label": best_entry['standard_label'],
            "confidence": confidence,
            "rationale": f"Matched keywords/category with score {best_score:.2f}"
        }, confidence
    else:
        # Low match score
        return {
            "pred_code": "UNKNOWN",
            "pred_label": "",
            "confidence": 0.05 + (0.1 * (best_score/2.0 if best_score > 0 else 0)),
            "rationale": f"Low match score ({best_score:.2f}) for span: {span}"
        }, 0.1
